<?php
declare(strict_types=1);
[$config,$pdo]=require __DIR__.'/h2-bootstrap.php';$db=new MediaCentre\Storage\Database($pdo);$uuid=MediaCentre\Shared\Uuid::random(...);
$admin=$db->one('SELECT * FROM admin_users WHERE login=?',['h3-test-admin']);$location=$db->one('SELECT id FROM locations ORDER BY created_at LIMIT 1');
$pair=new MediaCentre\Security\PairingRepository($db);$issued=$pair->issue($admin['id'],(int)$admin['auth_revision'],$location['id'],null,MediaCentre\Security\ClientAccess::SCOPES);
$api=new MediaCentre\Http\Api($config,dirname(__DIR__));$ip='test-'.bin2hex(random_bytes(8));
$payload=MediaCentre\Storage\Database::json(['code'=>$issued['code'],'client_name'=>'API test','client_version'=>'h3']);
$result=$api->handle('POST','/api/v1/pair',[],[],$payload,$ip);
if($result['status']!==200)throw new RuntimeException('API pair failed.');$paired=$result['body']['data'];
$validator=new MediaCentre\Shared\ContractValidator(dirname(__DIR__,2).'/contracts/v1/schema.json');
if(!$validator->valid('pairResponse',json_decode(json_encode($result['body']))))throw new RuntimeException('Pair contract failed.');
$headers=['authorization'=>'Bearer '.$paired['token']];
$wrongIdentity=$headers+['x-mediacentre-server-id'=>$uuid()];
if($api->handle('POST','/api/v1/client/heartbeat',[],$wrongIdentity,'{"client_version":"h3","uptime_seconds":10,"current_screen":"home"}')['status']!==401 || $db->one('SELECT last_seen_at FROM clients WHERE id=?',[$paired['client_id']])['last_seen_at']!==null)throw new RuntimeException('Heartbeat wrote to another server identity.');
$headers['x-mediacentre-server-id']=$paired['server_id'];
$call=fn($method,$path,$body='',array $extra=[],array $query=[])=>$api->handle($method,'/api/v1/'.$path,$query,$extra+$headers,$body,$ip);
$assert=fn($ok,$message)=>$ok ?: throw new RuntimeException($message);
foreach(['bootstrap','dashboard','weather','finance','radio/stations','client/preferences'] as $path)$assert($call('GET',$path)['status']===200,'Stored authorized read failed '.$path);
$bootstrapLocation=$call('GET','bootstrap')['body']['data']['settings']['location'];
$storedLocation=$db->one('SELECT latitude,longitude FROM locations WHERE id=?',[$location['id']]);
$assert($bootstrapLocation['latitude']===(string)$storedLocation['latitude'] && $bootstrapLocation['longitude']===(string)$storedLocation['longitude'],'Bootstrap location lacks fallback coordinates');
(new MediaCentre\Jobs\CollectionQueue($db))->sync(MediaCentre\Jobs\CollectionPlanner::describe($db));
$assert($call('POST','weather/refresh')['status']===202,'Client weather refresh was not queued');
$assert($call('POST','weather/refresh','{}')['status']===400,'Weather refresh accepted a body');
$assert($call('GET','weather','',[],['days'=>'14'])['status']===200,'Long weather horizon rejected');
$assert($call('GET','weather','',[],['days'=>'13'])['status']===400,'Unsupported weather horizon accepted');
$assert($api->handle('GET','/api/v1/bootstrap',[],['cookie'=>'MCADMIN=anything'],'')['status']===401,'Session cookie used as API token');
$assert($api->handle('POST','/api/v1/pair',[],[],$payload,$ip)['status']===401,'Used code accepted');
$assert($call('GET','client/preferences','',[],['client_id'=>$uuid()])['status']===400,'Foreign client selector accepted');
$preferences=$call('GET','client/preferences');$body=MediaCentre\Storage\Database::json(['revision'=>$preferences['body']['data']['revision'],'radio_volume'=>61]);
$assert($call('PATCH','client/preferences',$body)['status']===428,'Missing precondition accepted');
$etag=$preferences['headers']['ETag'];$assert($call('PATCH','client/preferences',$body,['if-match'=>$etag])['status']===200,'Preference save failed');
$assert($call('PATCH','client/preferences',$body,['if-match'=>$etag])['status']===412,'Stale precondition accepted');
$assert($call('PATCH','client/preferences','{"revision":2,"scopes":["home:control"]}',['if-match'=>$etag])['status']===400,'Scopes in preferences accepted');
$station=$uuid();(new MediaCentre\Radio\StationRepository($db))->create($station,'API station','https://example.invalid/stream',[],'RU');
$assert($call('PUT','radio/favorites/'.$station)['status']===200,'Favorite save failed');$assert($call('PUT','radio/favorites/'.$station)['status']===200,'Idempotent favorite failed');
$assert(count((new MediaCentre\Client\OrderedListRepository($db))->readFavorites($paired['client_id']))===1,'Favorite duplicate');
$assert($call('DELETE','radio/favorites/'.$station)['status']===200,'Favorite delete failed');
$assert($call('POST','client/heartbeat','{"client_version":"h3","uptime_seconds":10,"current_screen":"home"}')['status']===200,'Heartbeat persistence failed');
$assert($call('POST','finance','{}')['status']===405,'Finance write enabled');
$current=$call('GET','client/preferences');
$assert($call('PATCH','client/preferences',MediaCentre\Storage\Database::json(['revision'=>$current['body']['data']['revision'],'selected_station_id'=>$station]),['if-match'=>$current['headers']['ETag']])['status']===200,'Selected station save failed');
(new MediaCentre\Client\RightsRepository($db))->change($paired['client_id'],1,['preferences:read']);
$assert($call('GET','client/preferences')['body']['data']['selected_station_id']===null,'Preferences leaked forbidden radio selection');
$assert($call('GET','finance')['status']===403,'Finance scope bypass');$assert($call('PUT','radio/favorites/'.$station)['status']===403,'Favorite scope bypass');
$assert($call('POST','weather/refresh')['status']===403,'Weather refresh scope bypass');
$dashboard=$call('GET','dashboard');$assert($dashboard['status']===200 && $dashboard['body']['data']['finance']['data']['items']===[] && $dashboard['body']['data']['radio']['favorites']===[],'Dashboard leaked forbidden block');
$pair->revoke($paired['client_id'],2,$admin['id']);$assert($call('GET','bootstrap')['status']===401,'Revoked bearer accepted');
echo "PASS: anonymous pairing, bearer scopes, own settings/favorites, conflicts, read-only finance, heartbeat and revoke.\n";
